// Error page shown when a URL fails to load in the browser panel.
// The hedgehog image is embedded as base64 so this works in both dev and
// the packaged app without any extra asset-serving setup.
export const HOG_B64 =
  "";

export function buildErrorPage(url: string): string {
  const safeUrl = url
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

  const html =
    '<!DOCTYPE html><html lang="en"><head>' +
    '<meta charset="UTF-8"/>' +
    '<meta name="viewport" content="width=device-width,initial-scale=1.0"/>' +
    "<title>Page not available</title>" +
    "<style>" +
    "*{box-sizing:border-box;margin:0;padding:0}" +
    'body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;' +
    "background:#1a1a1a;color:#e0e0e0;display:flex;flex-direction:column;" +
    "align-items:center;justify-content:center;min-height:100vh;padding:24px;text-align:center;user-select:none}" +
    "img{width:160px;height:auto;margin-bottom:28px;filter:drop-shadow(0 8px 32px rgba(0,0,0,.6))}" +
    "h1{font-size:24px;font-weight:700;color:#fff;margin-bottom:10px;letter-spacing:-.3px}" +
    "p.sub{font-size:14px;color:#888;max-width:400px;line-height:1.65;margin-bottom:20px}" +
    ".url{background:#242424;border:1px solid #333;border-radius:6px;padding:8px 16px;" +
    'font-family:"SF Mono",Menlo,Consolas,monospace;font-size:12px;color:#999;' +
    "max-width:480px;width:100%;word-break:break-all;margin-bottom:28px}" +
    ".actions{display:flex;gap:10px}" +
    "button{background:#e74c3c;border:none;border-radius:6px;color:#fff;cursor:pointer;" +
    "font-size:14px;font-weight:600;padding:10px 22px;transition:background .15s}" +
    "button:hover{background:#c0392b}" +
    "button.s{background:#2a2a2a;border:1px solid #383838;color:#ccc}" +
    "button.s:hover{background:#333}" +
    ".badge{margin-top:40px;font-size:11px;color:#444;letter-spacing:.5px;text-transform:uppercase}" +
    ".badge b{color:#e74c3c;font-weight:700}" +
    "</style></head><body>" +
    '<img src="data:image/png;base64,' +
    HOG_B64 +
    '" alt="PostHog hedgehog"/>' +
    "<h1>This page couldn\u2019t be loaded</h1>" +
    '<p class="sub">The hedgehog tried its best, but the page is unavailable.<br/>' +
    "Check your connection or the URL and try again.</p>" +
    '<div class="url">' +
    safeUrl +
    "</div>" +
    '<div class="actions">' +
    '<button class="s" onclick="history.back()">&#8592; Go Back</button>' +
    '<button onclick="window.location.reload()">Try Again</button>' +
    "</div>" +
    '<div class="badge">Powered by <b>PostHog</b> Code</div>' +
    "</body></html>";

  return `data:text/html;charset=utf-8,${encodeURIComponent(html)}`;
}
